class Channel {
public:
    void send(int value) {
        {
            std::lock_guard lock{mutex_};
            values_.push(value);
        }
        ready_.notify_one();
    }

    void close() {
        {
            std::lock_guard lock{mutex_};
            closed_ = true;
        }
        ready_.notify_all();
    }

    std::optional<int> receive() {
        std::unique_lock lock{mutex_};
        ready_.wait(lock, [this] {
            return !values_.empty() || closed_;
        });

        if (values_.empty()) {
            return std::nullopt;
        }
        int value = values_.front();
        values_.pop();
        return value;
    }

private:
    std::mutex mutex_;
    std::condition_variable ready_;
    std::queue<int> values_;
    bool closed_ = false;
};

int main() {
    Channel channel;
    std::jthread producer{[&channel] {
        for (int value = 1; value <= 4; ++value) {
            channel.send(value);
        }
        channel.close();
    }};

    int received = 0;
    long total = 0;
    while (std::optional<int> value = channel.receive()) {
        ++received;
        total += *value;
    }

    std::cout << received << ' ' << total << '\n';
