#include <mutex>
#include <stop_token>
#include <thread>

class MarketFeed {
public:
    MarketFeed()
        // worker_ is initialised last because it is declared last, so the
        // lambda's `this` already points at a fully constructed mutex_ and
        // polls_. Members are initialised in DECLARATION order, not in the
        // order they appear in this list -- declaring worker_ first would
        // start a thread that reads members whose constructors have not run.
        : worker_{[this](std::stop_token stop) { run(stop); }} {}

    long polls() const {
        std::lock_guard lock{mutex_};
        return polls_;
    }

private:
    void run(std::stop_token stop) {
        // Tested at the TOP of the loop: a stop requested before this thread
        // was ever scheduled still ends it without doing a single poll.
        while (!stop.stop_requested()) {
            poll_once();
        }
    }

    void poll_once() {
        std::lock_guard lock{mutex_};
        ++polls_;
    }

    mutable std::mutex mutex_;
    long polls_ = 0;

    // Declared last on purpose, for both directions: constructed last, and
    // destroyed first. ~jthread requests stop and then joins, and it does so
    // while mutex_ and polls_ are still alive.
    std::jthread worker_;
};

#include <atomic>

// Two costs of thread_local: a dynamically initialized instance needs a
// per-thread guard check on access and runs its constructor once per THREAD
// rather than once per process, and every live thread holds its own copy, so
// a large object costs sizeof(object) x thread_count.

std::atomic<long> total_hits{0};
std::atomic<long> total_misses{0};

struct QuoteCounters {
    long hits = 0;
    long misses = 0;
};

// Thread-confined: nothing else can observe these, so plain ++ is race-free
// and needs no lock and no atomic RMW on the hot path.
thread_local QuoteCounters counters;

void record_hit() noexcept {
    ++counters.hits;
}

void record_miss() noexcept {
    ++counters.misses;
}

// The explicit boundary. Two atomic RMWs per flush instead of one per quote,
// paid for with publication freshness: the totals lag by up to one interval.
void flush_counters() noexcept {
    total_hits.fetch_add(counters.hits, std::memory_order_relaxed);
    total_misses.fetch_add(counters.misses, std::memory_order_relaxed);
    counters = QuoteCounters{};
}

// RAII form, so a worker that returns early or unwinds still publishes.
class CounterScope {
public:
    ~CounterScope() { flush_counters(); }
};

// These counters belong to the THREAD, not to a logical request. A task that
// suspends and resumes on a different pool worker sees that worker's
// instance; nothing migrates. Anything with request semantics must travel in
// the request object.

#include <array>
#include <cstddef>
#include <mutex>
#include <new>

class ShardedCounter {
public:
    static constexpr std::size_t shard_count = 8;

    void add(std::size_t shard_hint, long delta) {
        Shard& shard = shards_[shard_hint % shard_count];
        std::lock_guard lock{shard.mutex};
        shard.subtotal += delta;
    }

    // SNAPSHOT semantics, and that has to be written down. The shards are
    // read one at a time, so a writer can update shard 5 after shard 2 was
    // read; the returned number was never necessarily the simultaneous sum.
    // It is monotone and eventually complete, which is all a metric needs.
    // It is NOT a value you may then act on as if it were still true.
    long total() const {
        long sum = 0;
        for (const Shard& shard : shards_) {
            std::lock_guard lock{shard.mutex};
            sum += shard.subtotal;
        }
        return sum;
    }

private:
    // alignas keeps two shards off one cache line. Without it the mutexes
    // are adjacent and the line ping-pongs between cores -- the contention
    // sharding was meant to remove would come back through the hardware.
    struct alignas(64) Shard {
        mutable std::mutex mutex;
        long subtotal = 0;
    };

    // std::array, not std::vector. std::mutex is neither copyable nor
    // movable, so Shard is neither, and every vector operation that can
    // relocate elements (reserve, emplace_back, growth) requires a
    // move-insertable element type. A fixed array also guarantees the stable
    // addresses that anything holding a Shard& already depends on.
    std::array<Shard, shard_count> shards_{};
};

#include <functional>
#include <mutex>

struct Book {
    // mutex guards inventory, and only this book's inventory.
    int inventory = 0;
    mutable std::mutex mutex;
};

bool rebalance(Book& from, Book& to, int lots,
               const std::function<void(int)>& on_moved) {
    if (&from == &to) {
        return true;  // locking the same std::mutex twice is undefined
    }

    int remaining = 0;
    {
        // scoped_lock breaks hold-and-wait: it never blocks indefinitely on
        // the second mutex while retaining the first, so two callers arriving
        // in opposite orders cannot form a wait cycle.
        std::scoped_lock lock{from.mutex, to.mutex};

        if (from.inventory < lots) {
            return false;
        }
        from.inventory -= lots;
        to.inventory += lots;
        remaining = from.inventory;  // copy out what the callback needs
    }

    // Invoked with NO mutex held, and that is a correctness requirement.
    // on_moved is unknown code: it may allocate, log, take its own locks, or
    // call back into this module. Running it under from.mutex and to.mutex
    // silently imports every lock it acquires into this function's lock
    // order, and no reviewer of this file can see that order any more. It
    // also stretches the hold time by however long the caller's code runs.
    on_moved(remaining);
    return true;
}

#include <algorithm>
#include <cstddef>
#include <mutex>
#include <optional>
#include <shared_mutex>
