struct Backend {
    int id;
    std::string address;
};

class RouteTable {
public:
    std::optional<std::string> pick(std::size_t hash) const {
        std::shared_lock lock{mutex_};
        if (backends_.empty()) {
            return std::nullopt;
        }
        return backends_[hash % backends_.size()].address;
    }

    void install(std::vector<Backend> next) {
        // Built by the caller outside the lock; only the cheap move happens
        // inside the exclusive section.
        std::unique_lock lock{mutex_};
        backends_ = std::move(next);
    }

    bool retire_backend(int id) {
        {
            std::shared_lock lock{mutex_};
            if (!contains(id)) {
                return false;  // common case: no exclusive lock needed
            }
        }
        // The shared lock is RELEASED here. There is no upgrade operation in
        // std::shared_mutex, and inventing one is a classic deadlock: two
        // readers each holding shared ownership and each waiting for the
        // other to release before it can become exclusive.

        std::unique_lock lock{mutex_};
        // RE-CHECK. Between dropping the shared lock and taking the
        // exclusive one, another thread may have retired this backend or
        // replaced the whole table.
        auto position = std::ranges::find(backends_, id, &Backend::id);
        if (position == backends_.end()) {
            return false;
        }
        backends_.erase(position);
        return true;
    }

private:
    bool contains(int id) const {
        return std::ranges::find(backends_, id, &Backend::id) !=
               backends_.end();
    }

    // Justifying shared_mutex needs the read DURATION, not the read
    // percentage. Every reader writes shared reader bookkeeping whose cache
    // line then bounces between cores, so a read section as short as one
    // modulo and one string copy may well be slower here than a plain
    // std::mutex. Measure both under the real read/write mix before choosing,
    // and do not infer any fairness guarantee from the type name.
    mutable std::shared_mutex mutex_;
    std::vector<Backend> backends_;
};

#include <condition_variable>
