class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    void push(int value) {
        std::unique_lock lock{mutex_};
        not_full_.wait(lock, [this] {
            return items_.size() < capacity_;
        });

        items_.push(value);
        lock.unlock();          // publish first, then notify
        not_empty_.notify_one();
    }

    int pop() {
        std::unique_lock lock{mutex_};
        not_empty_.wait(lock, [this] {
            return !items_.empty();
        });

        int value = items_.front();
        items_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    // Two conditions, two condition variables. With one shared CV a
    // notify_one() after a pop could wake a blocked consumer instead of the
    // waiting producer; that consumer rechecks its predicate, finds the
    // queue empty, and parks again while the producer sleeps on. Correct but
    // wasteful at best, and it forces notify_all() to stay correct.
    std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::queue<int> items_;
    std::size_t capacity_;
};

#include <memory>
#include <mutex>
#include <string>
#include <unordered_map>

struct ReferenceData {
    int lot_size = 0;
    int tick_size = 0;
};

ReferenceData load_reference_data(const std::string& symbol);

class ReferenceCache {
public:
    const ReferenceData& get(const std::string& symbol) {
        Entry& entry = entry_for(symbol);

        // Called with table_mutex_ RELEASED: a slow load of one symbol must
        // not block lookups of every other symbol. Exactly one invocation
        // completes; concurrent callers for this symbol block until it does
        // and then observe its effects.
        //
        // If load_reference_data throws, the exception propagates to THIS
        // caller, entry.loaded stays unset, and a later call tries again.
        // Only the initialization goes in here -- unrelated slow work would
        // make every first caller for this symbol wait behind it.
        std::call_once(entry.loaded, [&] {
            entry.data = load_reference_data(symbol);
        });

        return entry.data;
    }

private:
    struct Entry {
        std::once_flag loaded;
        ReferenceData data{};
    };

    // std::once_flag is neither copyable nor movable, and it must keep the
    // same address for the whole program: a rehash that relocated it would
    // be a data race against a concurrent call_once on the old address.
    // unique_ptr gives the entries stable addresses independent of the
    // map's own storage.
    Entry& entry_for(const std::string& symbol) {
        std::lock_guard lock{table_mutex_};
        std::unique_ptr<Entry>& slot = entries_[symbol];
        if (!slot) {
            slot = std::make_unique<Entry>();
        }
        return *slot;
    }

    std::mutex table_mutex_;
    std::unordered_map<std::string, std::unique_ptr<Entry>> entries_;
};

#include <atomic>
#include <cstddef>
#include <exception>
#include <latch>
#include <mutex>
#include <thread>
#include <vector>

void start_subsystem(int id);   // may throw
void accept_traffic();
void report_startup_failure(std::exception_ptr error);

// Counts down on EVERY path, including exception unwinding. A subsystem that
// throws and simply returns would leave the coordinator waiting forever --
// the gate would be held closed by the one participant that already failed.
class LatchGuard {
public:
    explicit LatchGuard(std::latch& gate) noexcept : gate_(gate) {}
    ~LatchGuard() { gate_.count_down(); }
    LatchGuard(const LatchGuard&) = delete;
    LatchGuard& operator=(const LatchGuard&) = delete;

private:
    std::latch& gate_;
};

bool start_service(int subsystem_count) {
    // A latch counts down to one event that happens once: 'every subsystem
    // has reported'. It stays open afterwards and cannot be reset, which is
    // exactly right for a start gate. A repeated per-phase rendezvous is
    // std::barrier, which resets itself after each phase and can run a
    // completion step.
    std::latch ready{subsystem_count};
    std::atomic<bool> failed{false};
    std::exception_ptr first_error;
    std::mutex error_mutex;

    std::vector<std::jthread> subsystems;
    subsystems.reserve(static_cast<std::size_t>(subsystem_count));

    for (int id = 0; id < subsystem_count; ++id) {
        subsystems.emplace_back([&, id] {
            LatchGuard guard{ready};
            try {
                start_subsystem(id);
            } catch (...) {
                failed.store(true);
                std::lock_guard lock{error_mutex};
                if (!first_error) {
                    first_error = std::current_exception();
                }
            }
        });
    }

    ready.wait();  // returns once every subsystem has reported, ready or not

    if (failed.load()) {
        std::lock_guard lock{error_mutex};
        report_startup_failure(first_error);
        return false;
    }

    accept_traffic();
    return true;
}

