#include <functional>
#include <mutex>
#include <queue>
#include <utility>

class BoundedPool {
public:
    explicit BoundedPool(std::size_t capacity) : capacity_(capacity) {}

    // OVERLOAD POLICY: reject. submit() never blocks a producer and never
    // grows the queue, so overload becomes a visible, countable failure at
    // the caller instead of unbounded memory growth and rising tail latency.
    bool submit(std::function<void()> task) {
        {
            std::lock_guard lock{mutex_};
            if (closed_ || tasks_.size() == capacity_) {
                return false;
            }
            tasks_.push(std::move(task));
        }
        ready_.notify_one();  // publish under the lock, notify after
        return true;
    }

    // Idempotent: the second call sets an already-true flag and notifies
    // workers that have already exited, which is harmless. notify_all,
    // because one state change enables every parked worker at once.
    void close() {
        {
            std::lock_guard lock{mutex_};
            closed_ = true;
        }
        ready_.notify_all();
    }

private:
    // SHUTDOWN POLICY: drain. A worker returns only once the pool is closed
    // AND no queued task remains, so already-accepted work still runs.
    // Discarding pending work is an equally valid policy -- but the API has
    // to say which one it implements.
    void run() {
        for (;;) {
            std::function<void()> task;
            {
                std::unique_lock lock{mutex_};
                ready_.wait(lock, [this] {
                    return !tasks_.empty() || closed_;
                });

                if (tasks_.empty()) {
                    return;  // closed and drained
                }
                task = std::move(tasks_.front());  // move out under the lock
                tasks_.pop();
            }

            task();  // invoked with the mutex released
        }
    }

    std::mutex mutex_;
    std::condition_variable ready_;
    std::queue<std::function<void()>> tasks_;
    std::size_t capacity_;
    bool closed_ = false;
};

#include <limits>
#include <mutex>
#include <stdexcept>

class HierarchicalMutex {
public:
    explicit HierarchicalMutex(unsigned level) noexcept
        : level_(level) {}

    void lock() {
        check_order();
        mutex_.lock();
        take_level();
    }

    bool try_lock() {
        check_order();
        if (!mutex_.try_lock()) {
            return false;
        }
        take_level();
        return true;
    }

    void unlock() {
        // Restored BEFORE releasing, and restored on every exit path: an
        // exception thrown inside the critical section unwinds through
        // lock_guard's destructor, which calls unlock().
        current_level = previous_level_;
        mutex_.unlock();
    }

private:
    void check_order() const {
        if (level_ >= current_level) {
            // Fails on the thread that broke the order, at the moment it
            // broke it, with both levels in hand -- instead of two threads
            // hanging later with no evidence of who acquired what first.
            throw std::logic_error{"lock hierarchy violated"};
        }
    }

    void take_level() {
        previous_level_ = current_level;
        current_level = level_;
    }

    // One per thread: it describes what THIS thread currently holds.
    static thread_local unsigned current_level;

    std::mutex mutex_;
    unsigned level_;
    unsigned previous_level_ = 0;
};

thread_local unsigned HierarchicalMutex::current_level =
    std::numeric_limits<unsigned>::max();

// Enforces a global acquisition order, which rules out CIRCULAR WAIT: levels
// strictly decrease along any thread's held set, so no cycle can form. It
// says nothing about contention -- a hot mutex low in the hierarchy still
// convoys, and it does nothing for livelock in a try-lock retry loop, for
// priority inversion, or for a callback that acquires locks this order never
// enumerated.
